t>								<span class="form_tips" style="display: inline-block;margin-left: 10px">选择后，单行功能导航一行展示的数量(与功能导航效果设置无关)</span>							</div>						</div>					</if>				</td>			</tr>		</table>		<form name="myform" id="myform" action="" method="post">			<div class="table-list">				<table width="100%" cellspacing="0">					<colgroup>						<col/>						<col/>						<if condition="$many_city eq 1">							<col/>						</if>						<col/>						<col/>						<col width="180" align="center"/>						<col width="180" align="center"/>					</colgroup>					<thead>						<tr>							<th>编号</th>							<th>分类名称</th>							<th>排序</th><!--							<th>链接地址</th>--><!--							<th>图片(以下为强制小图，点击图片查看大图)</th>--><!--							<th class="textcenter">最后操作时间</th>-->							<th>状态</th>							<th class="textcenter">操作</th>						</tr>					</thead>					<tbody>						<if condition="is_array($result['list'])">							<volist name="result['list']" id="vo">								<tr>									<td>{pigcms{$vo.id}</td>									<td>{pigcms{$vo.name}</td>									<td>{pigcms{$vo.sort}</td><!--									<td><a href="{pigcms{$vo.url}" target="_blank">访问链接</a></td>--><!--									<td>--><!--										<img src="{pigcms{:file_domain()}/upload/adver/{pigcms{$vo.pic}" style="width:300px;height:80px;" class="view_msg"/>--><!--									</td>--><!--									<td class="textcenter">{pigcms{$vo.last_time|date='Y-m-d H:i:s',###}</td>-->									<td>									<if condition="$vo['status'] eq 1">										<font color="green">正常</font>									<elseif condition="$vo['status'] eq 0"/>										<font color="red">关闭</font>									</if></td>									<td class="textcenter">                                        <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('House/house_nav_edit',array('id'=>$vo['id'],'from_page'=>$_GET['from_page'],'source'=>$_GET['source']))}','编辑导航信息',1000,600,true,false,false,editbtn,'add',true,'refreshPage');">编辑</a>                                        | <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('House/house_nav_del')}">删除</a>                                    </td>                                </tr>							</volist>						<else/>							<tr><td class="textcenter red" colspan="9">列表为空！</td></tr>						</if>					</tbody>				</table>                <div class="textcenter pagebar">                    {pigcms{$result.pagebar}                </div>			</div>		</form>	</div><script>  // 一屏展示数量  $("#view_num").change(function(){    var view_num = $("#view_num").val();    layer.confirm("设置后所有未分配权限的"+"<?php echo (D('House_village')->getHouseAlias('house_name')?:'小区')?>"+"都将统一使用该展示数量，是否保存一屏展示数量效果?",{      btn: ['确认', '取消']    }, function () {      var url ="{pigcms{:U('House/set_village_nav')}";      $.post(url,{'view_num': view_num,'row_type': 'single'},function(data){        layer.msg(data['msg'])      },'json')    }, function(){      if(view_num == 5){        $("#view_num").attr('value',7);      }else{        $("#view_num").attr('value',5);      }    });  });</script><include file="Public:footer"/>
